// This bit for real. `applyStageBrief` was removed as dead code (nothing consumed
// the payload key it fed), but every fielded worker still destructured it and called
// it on the `apply-stage` path — the path #797 sends EVERY member down. The call
// threw after the PR was opened, so the update never completed, the mount never
// refreshed, and the member never received the worker that would stop calling it.
//
// The canary rehearsal cannot cover this: it runs the worker THIS REF SHIPS, by
// design, so it only ever exercises the new caller. This list is the substitute.
// An entry leaves it one full cycle after the fleet vendors a worker without the
// call — read the members' vendored workers to know that, never this repo's own.
// The paths moved with the flows (#1317), and BOTH are fielded right now. The worker resolves
// these against a FRESH CANON CLONE at HEAD rather than its own mount, so the surface a member
// calls is whatever ITS vendored worker names — and every member vendored a worker naming
// `updates/*` on 2026-08-24. The pack paths are what the worker names from this commit on; the
// `updates/*` re-exports stay callable until the fleet has vendored that worker, which is read
// off the members and never off this repo's own tree.
const fielded = {
  'updates/terminals.mjs': ['terminalFor'],
  'updates/engine-update.mjs': ['engineUpdate'],
  'updates/pack-update.mjs': ['packUpdate'],
  'packs/claudinite-lifecycle/updates/terminals.mjs': ['terminalFor'],
  'packs/claudinite-lifecycle/updates/engine-update.mjs': ['engineUpdate'],
  'packs/claudinite-lifecycle/updates/pack-update.mjs': ['packUpdate'],
};
for (const [mod, names] of Object.entries(fielded)) {
  const loaded = await import(`../${mod}`);
  for (const name of names) {
    assert.equal(typeof loaded[name], 'function',
      `${mod} no longer exports ${name} — every fielded worker calling it wedges on its next cycle`);
  }
}

// THE EXPIRY REGISTER, empty in the healthy state. An export kept alive only for
// stale callers gets an entry here when it goes in, because "remove this once the
// fleet catches up" as a comment is a reminder nobody rereads, and a shim kept
// forever is indistinguishable from one still needed. When an entry fires, do not
// bump the number: read a member's vendored worker, and if the call is gone delete
// the shim, its name from `fielded` above, and the entry.
const { ENGINE_VERSION } = await import('../engine/version.mjs');
const SHIMS = [];
for (const s of SHIMS) {
  assert.ok(ENGINE_VERSION < s.reviewAt,
    `engine ${ENGINE_VERSION} has passed ${s.reviewAt}: re-check whether ${s.module}'s ${s.name} shim `
    + `(added at engine ${s.since} for one-cycle-behind workers) is still called by any fielded worker. `
    + 'If not, delete the shim, its entry in the fielded surface above, and this entry.');
}

